function closeTemplateOrder(){const modal=$('#templateOrderModal');modal?.classList.remove('open');modal?.setAttribute('aria-hidden','true');document.body.style.overflow=''}
function closeConversationModal(){const modal=$('#conversationModal');modal?.classList.remove('open');modal?.setAttribute('aria-hidden','true');document.body.style.overflow='';if(state.conversationPoll){clearInterval(state.conversationPoll);state.conversationPoll=null}}
function renderCustomerConversation(conversation){
  const messages=(conversation.messages||[]).map(message=>`<article class="conversation-bubble ${message.senderType==='staff'?'staff':''}"><small>${esc(message.senderName)} · ${date(message.createdAt)}</small><p>${esc(message.text)}</p>${(message.attachments||[]).map(file=>`<a class="conversation-file" href="/api/conversations/${encodeURIComponent(conversation.id)}/files/${file.index}" target="_blank" rel="noopener">${esc(file.name)}</a>`).join('')}</article>`).join('');
  $('#conversationTitle').textContent=conversation.templateName||tx('محادثة ZEZO','ZEZO conversation');$('#conversationStatus').textContent=tx('الحالة: '+(conversation.status||'new'),'Status: '+(conversation.status||'new'));$('#conversationMessages').innerHTML=messages||`<div class="empty-state">${tx('اكتب رسالتك لبدء المحادثة.','Write your message to start the conversation.')}</div>`;
  const quote=conversation.quote,quoteHtml=quote?`<section class="conversation-quote"><b>${tx('عرض سعر','Quote')}: ${money(quote.amount)}</b><p>${esc(quote.scope)}</p>${quote.included?`<small>${esc(quote.included)}</small>`:''}${quote.exclusions?`<small>${tx('غير مشمول: ','Not included: ')}${esc(quote.exclusions)}</small>`:''}${quote.status==='sent'?`<button class="small-button accent" type="button" data-conversation-accept-quote>${tx('أوافق على عرض السعر','Accept this quote')}</button>`:`<span>${quote.status==='accepted'?tx('قُبل العرض','Quote accepted'):esc(quote.status)}</span>`}</section>`:'';
  $('#conversationQuote').innerHTML=quoteHtml;const official=$('#conversationOfficialOrder');official.hidden=!conversation.templateId;official.dataset.templateId=conversation.templateId||'';official.dataset.templateAction='order';official.dataset.conversationId=conversation.id;$('#conversationMessages').scrollTop=$('#conversationMessages').scrollHeight;
}
async function openCustomerConversation(conversation){state.activeConversationId=conversation.id;$('#conversationModal').classList.add('open');$('#conversationModal').setAttribute('aria-hidden','false');document.body.style.overflow='hidden';renderCustomerConversation(conversation);if(state.conversationPoll)clearInterval(state.conversationPoll);state.conversationPoll=setInterval(()=>refreshCustomerConversation().catch(()=>{}),12000)}
async function refreshCustomerConversation(){if(!state.activeConversationId)return;const response=await fetch(`/api/conversations/${encodeURIComponent(state.activeConversationId)}`),data=await response.json();if(!response.ok)throw new Error(data.error||'Conversation unavailable');renderCustomerConversation(data.conversation)}
