  if(kind==='ai-summary')return '<div class="ai-work-card"><label>'+tx('نص للمعاينة','Text to preview')+'<textarea id="aiInput" rows="7" placeholder="'+tx('الصق فقرة قصيرة هنا...','Paste a short paragraph here...')+'"></textarea></label><button data-ai-run>'+tx('أنشئ موجزاً تجريبياً','Create sample summary')+'</button><div id="aiResult" class="ai-result"></div></div>';
