  if(kind==='ai-quote')return '<div class="ai-work-card"><div class="demo-field-row"><label>'+tx('نوع المشروع','Project type')+'<select id="aiProjectType"><option>'+tx('صفحة هبوط','Landing page')+'</option><option>'+tx('موقع شركة','Company website')+'</option><option>'+tx('تطبيق كامل','Full app')+'</option></select></label><label>'+tx('عدد الخصائص','Feature count')+'<input id="aiFeatureCount" type="number" min="1" value="3"></label></div><button data-ai-run>'+tx('اقترح نطاقاً أولياً','Suggest a sample scope')+'</button><div id="aiResult" class="ai-result"></div><small>'+tx('ليس عرض سعر ملزماً؛ يحتاج النطاق إلى مراجعة الفريق.','Non-binding demo only; the team must review the scope.')+'</small></div>';
