  if(kind==='ai-flow')return '<div class="ai-flow"><ol id="demoFlowStages"><li class="active">'+tx('استلام الطلب','Receive request')+'</li><li>'+tx('تصنيف تلقائي','Auto classify')+'</li><li>'+tx('إشعار الفريق','Notify team')+'</li><li>'+tx('مراجعة بشرية','Human review')+'</li></ol><button type="button" data-demo-flow>'+tx('شغّل السيناريو التجريبي','Run sample workflow')+' ↗</button><p id="demoTabContent">'+tx('اضغط لتقدم خطوة خطوة؛ لا توجد خدمات مرتبطة.','Advance one stage at a time; no services are connected.')+'</p></div>';
