$('#activateForm').addEventListener('submit',async event=>{event.preventDefault();$('#activateError').textContent='';try{const data=await postJson('/api/auth/activate',{token:state.activationToken,password:event.currentTarget.elements.password.value});event.currentTarget.reset();history.replaceState({},'',location.pathname);if(sensitiveManagementRole(data.user.role)&&!data.user.mfaEnabled){await showManagementMfaSetup();return}state.dashboard=await(await fetch('/api/dashboard')).json();state.dashboardTab=dashboardTabForRole(data.user.role);renderDashboard(state.dashboard,state.dashboardTab);showToast(tx('تم تفعيل الحساب.','Account activated.'));openDashboard()}catch(e){$('#activateError').textContent=e.message}});
$('#mfaSetupForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,error=$('#mfaSetupError');error.textContent='';try{await postJson('/api/auth/mfa/enable',{code:form.elements.code.value});form.reset();$('#mfaSetupPanel').hidden=true;const response=await fetch('/api/dashboard'),data=await response.json();if(!response.ok)throw new Error(data.error||'Could not load workspace');state.dashboard=data;state.dashboardTab=dashboardTabForRole(data.role);renderDashboard(data,state.dashboardTab);showToast(tx('تم تفعيل التحقق بخطوتين.','Two-step verification enabled.'));openDashboard()}catch(e){error.textContent=e.message}});

