  const crmView=event.target.closest('[data-crm-view]');if(crmView){state.crmView=crmView.dataset.crmView;state.crmOpenId='';await loadCrmWorkspace();return}
  const crmOpen=event.target.closest('[data-crm-open]');if(crmOpen){state.crmOpenId=crmOpen.dataset.crmOpen;state.crmView='list';await loadCrmWorkspace();const record=$$('[data-crm-id]',$('#dashboardContent')).find(node=>node.dataset.crmId===state.crmOpenId);if(record){record.open=true;record.scrollIntoView({block:'center',behavior:state.motion?'auto':'smooth'})}return}
  const rankAction=event.target.closest('[data-rank-request-action]');if(rankAction){try{const response=await fetch(`/api/admin/rank-requests/${encodeURIComponent(rankAction.dataset.rankRequestAction)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:rankAction.dataset.decision})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Could not update rank request');await refreshDashboard('ranks');showToast(rankAction.dataset.decision==='approved'?tx('تم اعتماد الترقية؛ النسبة الجديدة للصفقات القادمة.','Promotion approved; the new rate applies to future sales.'):tx('تم رفض طلب الترقية.','Promotion request declined.'))}catch(e){showToast(e.message,true)}return}
  const copyTeamPortal=event.target.closest('[data-copy-team-portal]');if(copyTeamPortal){try{await navigator.clipboard.writeText(`${location.origin}/team`);showToast(tx('تم نسخ رابط بوابة الفريق.','Team portal link copied.'))}catch{showToast(tx('تعذر النسخ؛ انسخ الرابط الظاهر يدوياً.','Could not copy; copy the visible link manually.'),true)}return}
  const invitationResend=event.target.closest('[data-invitation-resend]');if(invitationResend){try{const response=await fetch(`/api/admin/invitations/${encodeURIComponent(invitationResend.dataset.invitationResend)}/resend`,{method:'POST'}),data=await response.json();if(!response.ok)throw new Error(data.error||'Invitation reissue failed');await refreshDashboard(state.dashboardTab);const result=$('#inviteResult'),link=`${location.origin}/activate?token=${encodeURIComponent(data.activationToken)}`;if(result)result.innerHTML=tx('رابط تفعيل جديد صالح 24 ساعة، ورابط لمرة واحدة. أرسله للموظف أو انسخه:','A fresh single-use activation link valid for 24 hours. Send it to the employee or copy it:')+`<br><a href="${esc(link)}" target="_blank" rel="noopener">${esc(link)}</a> <button class="small-button" type="button" data-copy-invite="${esc(link)}">${tx('نسخ الرابط','Copy link')}</button>`;showToast(data.emailQueued?tx('أُضيف بريد الدعوة إلى الإرسال.','Invitation email queued.'):tx('أُصدر رابط التفعيل الجديد.','New activation link issued.'))}catch(e){showToast(e.message,true)}return}
  const invitationAction=event.target.closest('[data-invitation-action]');if(invitationAction){try{await fetch(`/api/admin/invitations/${encodeURIComponent(invitationAction.dataset.invitationId)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:invitationAction.dataset.invitationAction})}).then(async r=>{const x=await r.json();if(!r.ok)throw new Error(x.error||'Invitation update failed');return x});await refreshDashboard('team');showToast(tx('تم إلغاء رابط الدعوة.','Invitation link revoked.'))}catch(e){showToast(e.message,true)}return}
  const taskDecision=event.target.closest('[data-task-decision]');if(taskDecision){try{await postJson(`/api/developer/projects/${encodeURIComponent(taskDecision.dataset.projectId)}/decision`,{decision:taskDecision.dataset.taskDecision});await refreshDashboard('development');showToast(taskDecision.dataset.taskDecision==='accept'?tx('قبلت المهمة.','Task accepted.'):tx('تم الاعتذار عن المهمة.','Task declined.'))}catch(e){showToast(e.message,true)}return}
  const copy=event.target.closest('[data-copy-referral]');if(copy){try{await navigator.clipboard.writeText(`${location.origin}${state.dashboard.referralLink}`);showToast(tx('تم نسخ رابطك.','Your link has been copied.'))}catch{showToast(tx('تعذر النسخ؛ حدّد الرابط وانسخه يدوياً.','Could not copy. Select and copy the link manually.'),true)}return}
  if(event.target.closest('#withdrawalRequest')){try{await postJson('/api/marketer/withdrawals',{});await refreshDashboard('referral');showToast(tx('تم إرسال طلب السحب للإدارة.','Withdrawal request sent to management.'))}catch(e){showToast(e.message,true)}return}
  if(event.target.closest('#whatsappOrder')){const phone=whatsappPhone('orders');if(!phone){showToast(tx('واتساب قسم الطلبات غير مربوط بعد.','Orders WhatsApp is not connected yet.'),true);return}const data=new FormData($('#projectForm')),followupId=shortToken('ZRI-'),parts=[tx('طلب إلى ZEZO','Enquiry to ZEZO'),`${tx('الخدمة','Service')}: ${$('#serviceSelect').selectedOptions[0]?.textContent||'—'}`,`${tx('التفاصيل','Details')}: ${data.get('details')||'—'}`,`ZEZO ${tx('رقم المتابعة','follow-up ID')}: ${followupId}`];if(state.referralCode)parts.push(`${tx('رمز الإحالة','Referral code')}: ${state.referralCode}`);emitReferralEvent('whatsapp_click',$('#serviceSelect').value||'',followupId);openWhatsAppWindow(buildWhatsAppUrl(phone,parts.join('\n')));return}
  const supportLink=event.target.closest('#customerSupport');if(supportLink){const phone=whatsappPhone('support');if(!phone){event.preventDefault();showToast(tx('خدمة العملاء عبر واتساب غير متاحة حالياً.','Customer support WhatsApp is unavailable right now.'),true);return}const followupId=shortToken('ZRI-'),parts=[tx('مرحباً ZEZO، أود الاستفسار عن خدماتكم.','Hello ZEZO, I would like to ask about your services.'),`ZEZO ${tx('رقم المتابعة','follow-up ID')}: ${followupId}`];if(state.referralCode)parts.push(`${tx('رمز الإحالة','Referral code')}: ${state.referralCode}`);supportLink.href=buildWhatsAppUrl(phone,parts.join('\n'));emitReferralEvent('whatsapp_click','',followupId);return}
