document.addEventListener('submit',async event=>{
  const form=event.target;
  if(!['pricingForm','newPriceForm','financeSettingsForm','expenseForm','financeFilterForm'].includes(form.id)&&!form.matches('[data-settlement],[data-withdrawal-update]'))return;
  event.preventDefault();event.stopImmediatePropagation();
  try{
    if(form.id==='pricingForm'){
      const prices=(state.dashboard.settings.prices||[]).map(price=>({id:price.id,price:form.elements[`price_${price.id}`].value,pricingMode:form.elements[`mode_${price.id}`].value,active:form.elements[`active_${price.id}`].checked}));
      await postJson('/api/admin/pricing',{prices,commissionHoldDays:form.elements.commissionHoldDays.value});await refreshDashboard('pricing');await loadPublic();showToast(tx('تم حفظ الأسعار. الأسعار الجديدة لا تغيّر الطلبات السابقة.','Prices saved. New prices do not change earlier requests.'));return;
    }
    if(form.id==='newPriceForm'){
      const input=Object.fromEntries(new FormData(form)),prices=[...(state.dashboard.settings.prices||[]),{...input,price:input.price===''?null:Number(input.price),active:true}];
      await postJson('/api/admin/pricing',{prices,commissionHoldDays:state.dashboard.settings.commissionHoldDays});await refreshDashboard('pricing');await loadPublic();showToast(tx('تمت إضافة السعر.','Price added.'));return;
    }
    if(form.id==='financeSettingsForm'){
      await postJson('/api/admin/finance/settings',Object.fromEntries(new FormData(form)));await refreshDashboard('finance');showToast(tx('تم حفظ إعدادات الخزينة.','Treasury settings saved.'));return;
    }
    if(form.id==='expenseForm'){
      await postJson('/api/admin/finance/expenses',Object.fromEntries(new FormData(form)));await refreshDashboard('finance');showToast(tx('تم تسجيل المصروف في الدفتر المالي.','Expense recorded in the finance ledger.'));return;
    }
    if(form.id==='financeFilterForm'){
      const query=new URLSearchParams(Object.fromEntries(new FormData(form)));const response=await fetch(`/api/admin/finance?${query}`),report=await response.json();if(!response.ok)throw new Error(report.error||'Could not load finance report');$('#financeReportMount').innerHTML=financeReportMarkup(report);return;
    }
    if(form.matches('[data-settlement]')){
      const response=await fetch(`/api/admin/leads/${encodeURIComponent(form.dataset.settlement)}/settlement`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))}),data=await response.json();if(!response.ok)throw new Error(data.error||'Could not save settlement');await refreshDashboard(state.dashboardTab==='finance'?'finance':'requests');showToast(data.settlement.lowMargin?tx('حُفظت التسوية مع تنبيه انخفاض الهامش.','Settlement saved with a low-margin warning.'):tx('حُفظت لقطة التسوية. الدفع يبقى منفصلاً.','Settlement snapshot saved. Payment remains separate.'));return;
    }
    if(form.matches('[data-withdrawal-update]')){
      const payload=Object.fromEntries(new FormData(form));payload.verified=Boolean(form.elements.verified?.checked);
      const response=await fetch(`/api/admin/withdrawals/${encodeURIComponent(form.dataset.withdrawalUpdate)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw new Error(data.error||'Could not update withdrawal');await refreshDashboard('withdrawals');showToast(payload.status==='paid'?tx('تم تسجيل التحويل بعد التحقق.','Transfer recorded after verification.'):payload.status==='rejected'?tx('رُفض الطلب وأُعيد المبلغ المتاح.','Request rejected and balance released.'):tx('تمت الموافقة؛ الطلب بانتظار التحويل اليدوي.','Approved; request is awaiting manual transfer.'));return;
    }
  }catch(error){showToast(error.message,true)}
},true);
